  ($q$t01$q$, $q$travel$q$, 0, $q$Where are you going? Bangkok, Phuket$q$, $j$[{"id":"wi-1","type":"wordIntro","word":{"thai":"ไป","roman":"pai","english":"go"},"source":"Essential Thai (Higbie), p.33"},{"id":"wi-2","type":"wordIntro","word":{"thai":"ไหน","roman":"nǎi","english":"where"},"source":"Essential Thai (Higbie), p.33"},{"id":"mc-146","type":"translationChoice","thai":"ไปไหน","roman":"pai nǎi","options":[{"text":"I'm going to Bangkok.","correct":false},{"text":"I'm going to Phuket.","correct":false},{"text":"I'm going out.","correct":false},{"text":"Where are you going?","correct":true}],"source":"Essential Thai (Higbie), p.33","parts":["ไป","ไหน"]},{"id":"sp-151","type":"speak","thai":"ไปไหน","roman":"pai nǎi","meaning":"Where are you going?","source":"Essential Thai (Higbie), p.33","parts":["ไป","ไหน"]},{"id":"wi-4","type":"wordIntro","word":{"thai":"เที่ยว","roman":"thîao","english":"go out / travel around"},"source":"Essential Thai (Higbie), p.33"},{"id":"so-147","type":"sentenceOrder","prompt":"I'm going out.","tileUnit":"word","words":{"a":{"roman":"pai","thai":"ไป"},"b":{"roman":"thîao","thai":"เที่ยว"},"x0":{"thai":"ไหน","roman":"nǎi"}},"poolOrder":["x0","a","b"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.33"},{"id":"wi-8","type":"wordIntro","word":{"thai":"กรุงเทพฯ","roman":"grung-thêep","english":"Bangkok"},"source":"Essential Thai (Higbie), p.33"},{"id":"mc-148","type":"translationChoice","thai":"ไปกรุงเทพฯ","roman":"pai grung-thêep","options":[{"text":"I'm going out.","correct":false},{"text":"I'm going to Bangkok.","correct":true},{"text":"I'm going to Phuket.","correct":false},{"text":"Where are you going?","correct":false}],"source":"Essential Thai (Higbie), p.33","parts":["ไป","กรุงเทพฯ"]},{"id":"wi-9","type":"wordIntro","word":{"thai":"ภูเก็ต","roman":"phuu-gèt","english":"Phuket"},"source":"Essential Thai (Higbie), p.33"},{"id":"sp-149","type":"speak","thai":"ไปภูเก็ต","roman":"pai phuu-gèt","meaning":"I'm going to Phuke