  ($q$t03$q$, $q$travel$q$, 2, $q$Airplane tickets, station, airport$q$, $j$[{"id":"wi-29","type":"wordIntro","word":{"thai":"เครื่องบิน","roman":"khrɯ̂ang-bin","english":"airplane"},"source":"Essential Thai (Higbie), p.136"},{"id":"mc-161","type":"translationChoice","thai":"ไปเครื่องบิน","roman":"pai khrɯ̂ang-bin","options":[{"text":"Where's the airport?","correct":false},{"text":"round trip","correct":false},{"text":"I'm going by plane.","correct":true},{"text":"one-way","correct":false}],"source":"Essential Thai (Higbie), p.136","parts":["ไป","เครื่องบิน"]},{"id":"sp-166","type":"speak","thai":"ไปเครื่องบิน","roman":"pai khrɯ̂ang-bin","meaning":"I'm going by plane.","source":"Essential Thai (Higbie), p.136","parts":["ไป","เครื่องบิน"]},{"id":"wi-31","type":"wordIntro","word":{"thai":"เดียว","roman":"diao","english":"single / only one"},"source":"Essential Thai (Higbie), p.138"},{"id":"so-162","type":"sentenceOrder","prompt":"one-way","tileUnit":"word","words":{"a":{"roman":"thîao","thai":"เที่ยว"},"b":{"roman":"diao","thai":"เดียว"},"x0":{"thai":"แท็กซี่","roman":"thák-sîi"},"x1":{"thai":"เครื่องบิน","roman":"khrɯ̂ang-bin"}},"poolOrder":["x1","x0","b","a"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.136"},{"id":"wi-33","type":"wordIntro","word":{"thai":"กลับ","roman":"glàp","english":"return / go back"},"source":"Essential Thai (Higbie), p.138"},{"id":"mc-163","type":"translationChoice","thai":"ไปกลับ","roman":"pai glàp","options":[{"text":"I'm going by plane.","correct":false},{"text":"one-way","correct":false},{"text":"round trip","correct":true},{"text":"Where's the airport?","correct":false}],"source":"Essential Thai (Higbie), p.136","parts":["ไป","กลับ"]},{"id":"wi-36","type":"wordIntro","word":{"thai":"สถานี","roman":"sà-thǎa-nee","english":"station"},"source":"Essential Thai (Higbie), p.137"},{"id":"wi-37","type":"wordIntro","word":{"thai":"สนามบิน","roman":"sà-nǎam-bin","english":"airport"},"source":"Essential Thai (Higbie), p.137"},{"id":"rp-167","type":"reply","context":[{"speaker":"M","thai":"ไปไหน","parts":["ไป","ไหน"],"roman":"pai nǎi","english":"Where are you going?"}],"replySpeaker":"F","thai":"ไปสนามบิน","roman":"pai sà-nǎam-bin","english":"To the airport.","options":[{"thai":"เที่ยวเดียว","roman":"thîao diao","correct":false},{"thai":"สถานีรถไฟ","roman":"sà-thǎa-nee rót-fai","correct":false},{"thai":"ไปสนามบิน","roman":"pai sà-nǎam-bin","correct":true}],"source":"Essential Thai (Higbie), p.136","parts":["ไป","สนามบิน"]},{"id":"wi-40","type":"wordIntro","word":{"thai":"อยู่","roman":"yùu","english":"be at / stay"},"source":"Essential Thai (Higbie), p.137"},{"id":"wi-41","type":"wordIntro","word":{"thai":"ที่ไหน","roman":"thîi-nǎi","english":"where?"},"source":"Essential Thai (Higbie), p.137"},{"id":"sp-164","type":"speak","thai":"สนามบินอยู่ที่ไหน","roman":"sà-nǎam-bin yùu thîi-nǎi","meaning":"Where's the airport?","source":"Essential Thai (Higbie), p.136","parts":["สนามบิน","อยู่","ที่ไหน"]},{"id":"so-165","type":"sentenceOrder","prompt":"Where's the train station?","tileUnit":"word","words":{"a":{"roman":"sà-thǎa-nee","thai":"สถานี"},"b":{"roman":"rót-fai","thai":"รถไฟ"},"c":{"roman":"yùu","thai":"อยู่"},"d":{"roman":"thîi-nǎi","thai":"ที่ไหน"},"x0":{"thai":"ภูเก็ต","roman":"phuu-gèt"},"x1":{"thai":"รถเมล์","roman":"rót-mee"}},"poolOrder":["x1","a","x0","d","c","b"],"correctOrder":["a","b","c","d"],"source":"Essential Thai (Higbie), p.136"},{"id":"match-168","type":"match","pairs":[{"thai":"เครื่องบิน","roman":"khrɯ̂ang-bin","english":"airplane"},{"thai":"เดียว","roman":"diao","english":"single / only one"},{"thai":"กลับ","roman":"glàp","english":"return / go back"},{"thai":"สถานี","roman":"sà-thǎa-nee","english":"station"},{"thai":"สนามบิน","roman":"sà-nǎam-bin","english":"airport"},{"thai":"อยู่","roman":"yùu","english":"be at / stay"},{"thai":"ที่ไหน","roman":"thîi-nǎi","english":"where?"}],"source":"Essential Thai (Higbie), p.136"}]$j$::jsonb),
  ($q$t04$q$, $q$travel$q$, 3, $q$Buying tickets, getting on the bus$q$, $j$[{"id":"wi-45","type":"wordIntro","word":{"thai":"เอา","roman":"ao","english":"want / take"},"source":"Essential Thai (Higbie), p.138"},{"id":"wi-46","type":"wordIntro","word":{"thai":"ตั๋ว","roman":"tǔa","english":"ticket"},"source":"Essential Thai (Higbie), p.138"},{"id":"mc-169","type":"translationChoice","thai":"เอาตั๋วไปกรุงเทพฯ","roman":"ao tǔa pai grung-thêep","options":[{"text":"A ticket to Bangkok, please.","correct":true},{"text":"two tickets","correct":false},{"text":"How many tickets?","correct":false},{"text":"Where's the bus stop?","correct":false}],"source":"Essential Thai (Higbie), p.138","parts":["เอา","ตั๋ว","ไป","กรุงเทพฯ"]},{"id":"sp-174","type":"speak","thai":"เอาตั๋วไปกรุงเทพฯ","roman":"ao tǔa pai grung-thêep","meaning":"A ticket to Bangkok, please.","source":"Essential Thai (Higbie), p.138","parts":["เอา","ตั๋ว","ไป","กรุงเทพฯ"]},{"id":"wi-48","type":"wordIntro","word":{"thai":"กี่","roman":"gìi","english":"how many?"},"source":"Essential Thai (Higbie), p.138"},{"id":"wi-49","type":"wordIntro","word":{"thai":"ใบ","roman":"bai","english":"classifier for tickets"},"source":"Essential Thai (Higbie), p.138"},{"id":"so-170","type":"sentenceOrder","prompt":"How many tickets?","tileUnit":"word","words":{"a":{"roman":"ao","thai":"เอา"},"b":{"roman":"gìi","thai":"กี่"},"c":{"roman":"bai","thai":"ใบ"},"x0":{"thai":"สนามบิน","roman":"sà-nǎam-bin"},"x1":{"thai":"กลับ","roman":"glàp"}},"poolOrder":["a","x1","b","x0","c"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.138"},{"id":"wi-51","type":"wordIntro","word":{"thai":"สอง","roman":"sɔ̌ɔng","english":"two"},"source":"Essential Thai (Higbie), p.138"},{"id":"mc-171","type":"translationChoice","thai":"สองใบ","roman":"sɔ̌ɔng bai","options":[{"text":"A ticket to Bangkok, please.","correct":false},{"text":"How many tickets?","correct":false},{"text":"two tickets","correct":true},{"text":"Where's the bus stop?","correct":false}],"source":"Essential Thai (Higbie), p.138","parts":["สอง","ใบ"]},{"id":"wi-53","type":"wordIntro","word":{"thai":"ป้าย","roman":"pâai","english":"bus stop / sign"},"source":"Essential Thai (Higbie), p.137"},{"id":"sp-172","type":"speak","thai":"ป้ายรถเมล์อยู่ที่ไหน","roman":"pâai rót-mee yùu thîi-nǎi","meaning":"Where's the bus stop?","source":"Essential Thai (Higbie), p.138","parts":["ป้าย","รถเมล์","อยู่","ที่ไหน"]},{"id":"wi-54","type":"wordIntro","word":{"thai":"ขึ้น","roman":"khɯ̂n","english":"get on"},"source":"Essential Thai (Higbie), p.139"},{"id":"so-173","type":"sentenceOrder","prompt":"Where do I get on?","tileUnit":"word","words":{"a":{"roman":"khɯ̂n","thai":"ขึ้น"},"b":{"roman":"thîi-nǎi","thai":"ที่ไหน"},"x0":{"thai":"ไหน","roman":"nǎi"},"x1":{"thai":"เครื่องบิน","roman":"khrɯ̂ang-bin"}},"poolOrder":["a","x1","b","x0"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.138"},{"id":"rp-175","type":"reply","context":[{"speaker":"M","thai":"เอากี่ใบ","parts":["เอา","กี่","ใบ"],"roman":"ao gìi bai","english":"How many tickets?"}],"replySpeaker":"F","thai":"สองใบ","roman":"sɔ̌ɔng bai","english":"Two.","options":[{"thai":"ขึ้นที่ไหน","roman":"khɯ̂n thîi-nǎi","correct":false},{"thai":"สองใบ","roman":"sɔ̌ɔng bai","correct":true},{"thai":"ป้ายรถเมล์","roman":"pâai rót-mee","correct":false}],"source":"Essential Thai (Higbie), p.138","parts":["สอง","ใบ"]},{"id":"match-176","type":"match","pairs":[{"thai":"เอา","roman":"ao","english":"want / take"},{"thai":"ตั๋ว","roman":"tǔa","english":"ticket"},{"thai":"กี่","roman":"gìi","english":"how many?"},{"thai":"ใบ","roman":"bai","english":"classifier for tickets"},{"thai":"สอง","roman":"sɔ̌ɔng","english":"two"},{"thai":"ป้าย","roman":"pâai","english":"bus stop / sign"},{"thai":"ขึ้น","roman":"khɯ̂n","english":"get on"}],"source":"Essential Thai (Higbie), p.138"}]$j$::jsonb),
